function renderMyCourses(){var s=requireLogin("student");if(!s)return;var box=document.getElementById("my-courses-container");if(!box)return;var codes=getEnrolledCourseCodes(s.username),courses=getAllCourses(),html="";for(var i=0;i<codes.length;i++)for(var j=0;j<courses.length;j++)if(courses[j].code.toLowerCase()===codes[i].toLowerCase()){var info=getCourseProgress(s.username,courses[j].code),done=info.completed===true;var rating=done?(getCourseRatings(s.username)[courses[j].code.toUpperCase()]||0):0;var stars='';for(var rs=1;rs<=5;rs++)stars+='<button type="button" class="rating-star" data-code="'+courses[j].code+'" data-rating="'+rs+'"><i class="fa-'+(rs<=rating?'solid':'regular')+' fa-star"></i></button>';html+='<div class="panel" style="margin-bottom:16px"><div class="panel-head"><div><h3>'+courses[j].name+'</h3><p style="margin:0;color:var(--muted-dim)">'+courses[j].code+' · '+courses[j].instructor+'</p></div><span class="pill '+(done?'active':'')+'">'+(done?'Completed':info.progress+'%')+'</span></div><p>'+courses[j].desc+'</p><div class="progress-row"><div class="progress-label"><span>Progress</span><span>'+info.progress+'%</span></div><div class="progress-bar"><span style="width:'+info.progress+'%"></span></div></div><a class="btn btn-primary btn-sm" href="/course-learning?course='+encodeURIComponent(courses[j].code)+'">'+(done?'Review Course':'Continue Learning')+'</a>'+(done?' <a class="btn btn-ghost btn-sm" href="/certificate?course='+encodeURIComponent(courses[j].code)+'">Certificate</a><div style="margin-top:14px"><small style="color:var(--muted-dim)">Rate this course</small><div class="rating-stars">'+stars+'</div></div>':'')+'</div>';}box.innerHTML=html||'<div class="placeholder-box">No enrolled courses yet. <a href="/courses">Browse the catalog</a> to enroll.</div>';}document.addEventListener("DOMContentLoaded",function(){renderMyCourses();document.addEventListener("click",function(e){var b=e.target.closest?e.target.closest(".rating-star"):null;if(b){var s=getSession();saveCourseRating(s.username,b.getAttribute("data-code"),b.getAttribute("data-rating"));renderMyCourses();}});});
